#include "cache.h"
#include <sqlite3.h>
#include <memory>
#include "schema_migrator.h"
#include "sqlite_connection.h"

namespace gdl::cache { namespace {
using Stmt=std::unique_ptr<sqlite3_stmt,decltype(&sqlite3_finalize)>;
CacheError Err(sqlite3*db,CacheOperation op,const std::string&p,const std::string&c){int e=sqlite3_extended_errcode(db);return{.operation=op,.primary_code=e&0xff,.extended_code=e,.path=p,.context=c+": "+sqlite3_errmsg(db)};}
CacheResult<Stmt> Prep(sqlite3*db,const std::string&p,const char*sql){sqlite3_stmt*r=nullptr;int rc=sqlite3_prepare_v2(db,sql,-1,&r,nullptr);if(rc!=SQLITE_OK)return CacheResult<Stmt>::Failure(Err(db,CacheOperation::kPrepare,p,sql));return CacheResult<Stmt>::Success(Stmt(r,sqlite3_finalize));}
CacheResult<void> TextBind(sqlite3*db,sqlite3_stmt*s,int i,const std::string&v,const std::string&p){int rc=sqlite3_bind_text(s,i,v.c_str(),-1,SQLITE_TRANSIENT);return rc==SQLITE_OK?CacheResult<void>::Success():CacheResult<void>::Failure(Err(db,CacheOperation::kBind,p,"bind text"));}
std::string Text(sqlite3_stmt*s,int i){auto*p=sqlite3_column_text(s,i);return p?std::string(reinterpret_cast<const char*>(p)):std::string();}
SchemaDefinition Schema(){return{.table_name="tracker_etag_cache",.current_version=1,.create_table_sql="CREATE TABLE tracker_etag_cache(url TEXT PRIMARY KEY,etag TEXT NOT NULL,content TEXT NOT NULL,timestamp INTEGER NOT NULL)",.current_columns={{"url","TEXT",false,"",1},{"etag","TEXT",true,"",0},{"content","TEXT",true,"",0},{"timestamp","INTEGER",true,"",0}}};}
}
class TrackerETagCache::Impl{public:CacheResult<void> Init(const String&p){auto o=connection_.Open(p,detail::TrackerCacheOpenOptions());if(o.HasError())return o;auto s=EnsureSchema(connection_,Schema());if(s.HasError()){connection_.Close();return s;}return CacheResult<void>::Success();}CacheResult<void> Close(){return connection_.Close();}SqliteConnection& C(){return connection_;}private:SqliteConnection connection_;};
TrackerETagCache::TrackerETagCache():impl_(std::make_unique<Impl>()){} TrackerETagCache::~TrackerETagCache()=default;
CacheResult<void> TrackerETagCache::Initialize(const String&p){return impl_->Init(p);} CacheResult<void> TrackerETagCache::Uninitialize(){return impl_->Close();}
CacheResult<void> TrackerETagCache::SetEntry(const TrackerETagEntry&e){return impl_->C().Use<void>(CacheOperation::kStep,"upsert tracker",[&](sqlite3*db,const std::string& database_path){auto p=Prep(db,database_path,"INSERT INTO tracker_etag_cache(url,etag,content,timestamp) VALUES(?,?,?,?) ON CONFLICT(url) DO UPDATE SET etag=excluded.etag,content=excluded.content,timestamp=excluded.timestamp");if(p.HasError())return CacheResult<void>::Failure(p.GetError());for(auto [i,v]:{std::pair{1,&e.url},{2,&e.etag},{3,&e.content}}){auto b=TextBind(db,p.Value().get(),i,*v,database_path);if(b.HasError())return b;}if(sqlite3_bind_int64(p.Value().get(),4,e.timestamp)!=SQLITE_OK)return CacheResult<void>::Failure(Err(db,CacheOperation::kBind,database_path,"bind timestamp"));int rc=sqlite3_step(p.Value().get());return rc==SQLITE_DONE?CacheResult<void>::Success():CacheResult<void>::Failure(Err(db,CacheOperation::kStep,database_path,"upsert tracker"));});}
CacheResult<std::optional<TrackerETagEntry>> TrackerETagCache::GetEntry(const std::string&url){return impl_->C().Use<std::optional<TrackerETagEntry>>(CacheOperation::kInspect,"get tracker",[&](sqlite3*db,const std::string& database_path){auto p=Prep(db,database_path,"SELECT url,etag,content,timestamp FROM tracker_etag_cache WHERE url=?");if(p.HasError())return CacheResult<std::optional<TrackerETagEntry>>::Failure(p.GetError());auto b=TextBind(db,p.Value().get(),1,url,database_path);if(b.HasError())return CacheResult<std::optional<TrackerETagEntry>>::Failure(b.GetError());int rc=sqlite3_step(p.Value().get());if(rc==SQLITE_DONE)return CacheResult<std::optional<TrackerETagEntry>>::Success(std::nullopt);if(rc!=SQLITE_ROW)return CacheResult<std::optional<TrackerETagEntry>>::Failure(Err(db,CacheOperation::kStep,database_path,"get tracker"));return CacheResult<std::optional<TrackerETagEntry>>::Success(TrackerETagEntry{Text(p.Value().get(),0),Text(p.Value().get(),1),Text(p.Value().get(),2),sqlite3_column_int64(p.Value().get(),3)});});}
CacheResult<void> TrackerETagCache::DeleteEntry(const std::string&url){return impl_->C().Use<void>(CacheOperation::kStep,"delete tracker",[&](sqlite3*db,const std::string& database_path){auto p=Prep(db,database_path,"DELETE FROM tracker_etag_cache WHERE url=?");if(p.HasError())return CacheResult<void>::Failure(p.GetError());auto b=TextBind(db,p.Value().get(),1,url,database_path);if(b.HasError())return b;int rc=sqlite3_step(p.Value().get());return rc==SQLITE_DONE?CacheResult<void>::Success():CacheResult<void>::Failure(Err(db,CacheOperation::kStep,database_path,"delete tracker"));});}
CacheResult<void> TrackerETagCache::ClearAllEntries(){return impl_->C().Use<void>(CacheOperation::kStep,"clear trackers",[&](sqlite3*db,const std::string& database_path){int rc=sqlite3_exec(db,"DELETE FROM tracker_etag_cache",nullptr,nullptr,nullptr);return rc==SQLITE_OK?CacheResult<void>::Success():CacheResult<void>::Failure(Err(db,CacheOperation::kStep,database_path,"clear trackers"));});}
CacheResult<std::vector<TrackerETagEntry>> TrackerETagCache::GetAllEntries(){return impl_->C().Use<std::vector<TrackerETagEntry>>(CacheOperation::kInspect,"all trackers",[&](sqlite3*db,const std::string& database_path){auto p=Prep(db,database_path,"SELECT url,etag,content,timestamp FROM tracker_etag_cache ORDER BY timestamp DESC");if(p.HasError())return CacheResult<std::vector<TrackerETagEntry>>::Failure(p.GetError());std::vector<TrackerETagEntry> out;for(;;){int rc=sqlite3_step(p.Value().get());if(rc==SQLITE_DONE)return CacheResult<std::vector<TrackerETagEntry>>::Success(std::move(out));if(rc!=SQLITE_ROW)return CacheResult<std::vector<TrackerETagEntry>>::Failure(Err(db,CacheOperation::kStep,database_path,"all trackers"));out.push_back({Text(p.Value().get(),0),Text(p.Value().get(),1),Text(p.Value().get(),2),sqlite3_column_int64(p.Value().get(),3)});}});}
CacheResult<size_t> TrackerETagCache::GetTotalCount(){return impl_->C().Use<size_t>(CacheOperation::kInspect,"count trackers",[&](sqlite3*db,const std::string& database_path){auto p=Prep(db,database_path,"SELECT count(*) FROM tracker_etag_cache");if(p.HasError())return CacheResult<size_t>::Failure(p.GetError());int rc=sqlite3_step(p.Value().get());return rc==SQLITE_ROW?CacheResult<size_t>::Success(static_cast<size_t>(sqlite3_column_int64(p.Value().get(),0))):CacheResult<size_t>::Failure(Err(db,CacheOperation::kStep,database_path,"count trackers"));});}
}
